#!/usr/bin/env node
/**
 * Optibench Workstation - icon & installer artwork pipeline.
 *
 *   npm run icons        (node scripts/build-icons.mjs)
 *
 * Sources (hand-authored):
 *   build/icon.svg          master app icon (used for >= 64 px)
 *   build/icon-small.svg    heavier-stroke variant (used for 16-48 px)
 *
 * Generated by this script (do not edit by hand - edit the code below):
 *   build/file-icon.svg       .obw document icon
 *   build/logo-wordmark.svg   icon + "Optibench Workstation" wordmark (text as paths)
 *   build/icons/{16..1024}.png, build/icon.png (512)
 *   build/icon.ico            16/24/32/48/64/128/256
 *   build/file-icon.ico       16/24/32/48/64/128/256
 *   build/icon.iconset/*, build/file-icon.iconset/*   (macOS - see below)
 *   build/installerSidebar.bmp (164x314, 24-bit), build/installerHeader.bmp (150x57, 24-bit)
 *
 * macOS: .icns files must be produced with Apple's iconutil, which only exists on macOS:
 *   iconutil -c icns build/icon.iconset -o build/icon.icns
 *   iconutil -c icns build/file-icon.iconset -o build/file-icon.icns
 * When this script runs on macOS it does that automatically. If build/icon.icns is absent,
 * electron-builder falls back to converting build/icon.png.
 */
import { mkdir, readFile, writeFile, rm } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import sharp from 'sharp';
import pngToIco from 'png-to-ico';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const BUILD = path.join(ROOT, 'build');
const ICONS = path.join(BUILD, 'icons');
const b = (...p) => path.join(BUILD, ...p);

const PALETTE = {
  bg: '#0B0F17',
  panel: '#111826',
  text: '#E6EDF7',
  muted: '#8A97AD',
  cyan: '#3DE0FF',
  violet: '#8B5CFF',
  spectrum: ['#FF3B5C', '#FF8A3D', '#FFD23F', '#4BE37A', '#3DE0FF', '#4A7BFF', '#8B5CFF'],
};

// ---------------------------------------------------------------------------
// Monoline geometric glyphs (text converted to paths, no font dependency).
// Units: baseline y=100, x-height top y=50, cap/ascender y=28, descender y=122.
// Every glyph is drawn as stroke centre-lines with stroke-width `w`.
// ---------------------------------------------------------------------------
const f = (n) => +n.toFixed(2);
const circle = (cx, cy, r) =>
  `M${f(cx - r)} ${f(cy)}A${f(r)} ${f(r)} 0 1 0 ${f(cx + r)} ${f(cy)}A${f(r)} ${f(r)} 0 1 0 ${f(cx - r)} ${f(cy)}`;

function glyph(ch, x, w) {
  const h = w / 2;
  const R = 27 - h; // x-height bowl radius (outer edge overshoots by 2 units)
  const cx = x + h + R;
  const c40 = Math.cos((40 * Math.PI) / 180);
  const s40 = Math.sin((40 * Math.PI) / 180);
  let d = '';
  let dots = [];
  let adv;
  switch (ch) {
    case 'O': {
      const Rc = 38 - h;
      d = circle(x + h + Rc, 64, Rc);
      adv = 2 * (Rc + h);
      break;
    }
    case 'W':
      d = `M${f(x + h)} 28L${f(x + 19)} 100L${f(x + 38)} 46L${f(x + 57)} 100L${f(x + 76 - h)} 28`;
      adv = 76;
      break;
    case 'w':
      d = `M${f(x + h)} 50L${f(x + 15)} 100L${f(x + 31)} 58L${f(x + 47)} 100L${f(x + 62 - h)} 50`;
      adv = 62;
      break;
    case 'o':
      d = circle(cx, 75, R);
      adv = 2 * (R + h);
      break;
    case 'p':
      d = `M${f(x + h)} 50V122` + circle(cx, 75, R);
      adv = 2 * (R + h);
      break;
    case 'b':
      d = `M${f(x + h)} 28V100` + circle(cx, 75, R);
      adv = 2 * (R + h);
      break;
    case 'a':
      d = circle(cx, 75, R) + `M${f(cx + R)} 50V100`;
      adv = 2 * (R + h);
      break;
    case 'e':
      d = `M${f(x + h)} 75H${f(cx + R)}A${f(R)} ${f(R)} 0 1 0 ${f(cx + R * c40)} ${f(75 + R * s40)}`;
      adv = 2 * (R + h);
      break;
    case 'c':
      d = `M${f(cx + R * c40)} ${f(75 - R * s40)}A${f(R)} ${f(R)} 0 1 0 ${f(cx + R * c40)} ${f(75 + R * s40)}`;
      adv = 2 * (R + h) - 4;
      break;
    case 'n':
    case 'h':
      d = `M${f(x + h)} ${ch === 'h' ? 28 : 50}V100M${f(x + h)} 100V75A${f(R)} ${f(R)} 0 0 1 ${f(x + h + 2 * R)} 75V100`;
      adv = 2 * (R + h);
      break;
    case 't':
      d = `M${f(x + 13)} 32V100M${f(x)} 50H${f(x + 28)}`;
      adv = 28;
      break;
    case 'i':
      d = `M${f(x + h)} 50V100`;
      dots = [[x + h, 34, h * 1.2]];
      adv = w;
      break;
    case 'r':
      d = `M${f(x + h)} 50V100M${f(x + h)} 77A${f(R)} ${f(R)} 0 0 1 ${f(x + h + R)} ${f(75 - R)}H${f(x + h + R + 8)}`;
      adv = h + R + 8 + h;
      break;
    case 'k':
      d = `M${f(x + h)} 28V100M${f(x + 40)} 50L${f(x + h + 2)} 82M${f(x + h + 13)} 72L${f(x + 42)} 100`;
      adv = 44;
      break;
    case 's': {
      const rx = 16;
      const sx = x + h + rx;
      const ry1 = (75 - (48 + h)) / 2;
      const c1 = 48 + h + ry1;
      const ry2 = (102 - h - 75) / 2;
      const c2 = 75 + ry2;
      const c35 = Math.cos((35 * Math.PI) / 180);
      const s35 = Math.sin((35 * Math.PI) / 180);
      d =
        `M${f(sx + rx * c35)} ${f(c1 - ry1 * s35)}A${rx} ${f(ry1)} 0 1 0 ${f(sx)} 75` +
        `A${rx} ${f(ry2)} 0 1 1 ${f(sx - rx * c35)} ${f(c2 + ry2 * s35)}`;
      adv = 2 * (rx + h);
      break;
    }
    case '.':
      dots = [[x + h, 100 - h * 1.2, h * 1.2]];
      adv = w;
      break;
    case ' ':
      adv = 26;
      break;
    default:
      throw new Error(`glyph not defined: ${ch}`);
  }
  return { d, dots, adv };
}

/** Lay out a string; returns { svg, width } in glyph units, origin at x=0. */
function text(str, { w = 10, color = '#fff', tracking = 9 } = {}) {
  let x = 0;
  let d = '';
  const dots = [];
  for (const ch of str) {
    const g = glyph(ch, x, w);
    d += g.d;
    dots.push(...g.dots);
    x += g.adv + (ch === ' ' ? 0 : tracking);
  }
  const width = x - tracking;
  const svg =
    `<path d="${d}" fill="none" stroke="${color}" stroke-width="${w}" stroke-linecap="butt" stroke-linejoin="round"/>` +
    dots.map(([cx, cy, r]) => `<circle cx="${f(cx)}" cy="${f(cy)}" r="${f(r)}" fill="${color}"/>`).join('');
  return { svg, width };
}

const spectrumStops = (op = 1) =>
  PALETTE.spectrum
    .map((c, i) => `<stop offset="${f(i / (PALETTE.spectrum.length - 1))}" stop-color="${c}" stop-opacity="${op}"/>`)
    .join('');

// Strip XML prolog/comments so an SVG file can be nested inside another SVG.
// Ids are prefixed to avoid clashes when the same icon is embedded twice.
function nestable(svgSource, prefix) {
  return svgSource
    .replace(/<\?xml[^>]*\?>/g, '')
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/id="([^"]+)"/g, `id="${prefix}$1"`)
    .replace(/url\(#([^)]+)\)/g, `url(#${prefix}$1)`)
    .trim();
}
function embed(svgSource, prefix, x, y, size) {
  return nestable(svgSource, prefix).replace(
    /<svg([^>]*?)width="1024" height="1024"/,
    `<svg$1x="${x}" y="${y}" width="${size}" height="${size}"`,
  );
}

// ---------------------------------------------------------------------------
// Generated SVG artwork
// ---------------------------------------------------------------------------
function fileIconSvg() {
  // .obw label in dark ink on a laser-cyan pill
  const label = text('.obw', { w: 16, color: '#0B1230', tracking: 10 });
  const scale = 2.2;
  const lw = label.width * scale;
  const lx = 520 - lw / 2;
  const ly = 798 - 75 * scale; // centre the x-height band on y=798
  return `<?xml version="1.0" encoding="UTF-8"?>
<!-- Optibench Workstation - .obw document icon. GENERATED by scripts/build-icons.mjs; edit the script, not this file. -->
<svg xmlns="http://www.w3.org/2000/svg" width="1024" height="1024" viewBox="0 0 1024 1024">
  <defs>
    <linearGradient id="page" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stop-color="#121A44"/>
      <stop offset="1" stop-color="#2C1D78"/>
    </linearGradient>
    <linearGradient id="fold" x1="0" y1="1" x2="1" y2="0">
      <stop offset="0" stop-color="#6C7BFF"/>
      <stop offset="1" stop-color="#A9B4FF"/>
    </linearGradient>
    <linearGradient id="glass" x1="380" y1="200" x2="680" y2="560" gradientUnits="userSpaceOnUse">
      <stop offset="0" stop-color="#FFFFFF" stop-opacity="0.3"/>
      <stop offset="1" stop-color="#FFFFFF" stop-opacity="0.06"/>
    </linearGradient>
    <clipPath id="clip"><path d="M232 64H640L856 280V912Q856 960 808 960H232Q184 960 184 912V112Q184 64 232 64Z"/></clipPath>
  </defs>
  <path d="M232 64H640L856 280V912Q856 960 808 960H232Q184 960 184 912V112Q184 64 232 64Z" fill="url(#page)"/>
  <g clip-path="url(#clip)">
    <path d="M150 500L430 404" stroke="#FFFFFF" stroke-width="30"/>
    ${(() => {
      // spectral fan leaving the right face of the prism
      const e1 = [575, 380], e2 = [606, 444];
      const ys = [430, 480, 530, 580, 630, 680, 730, 780];
      return PALETTE.spectrum
        .map((c, k) => {
          const p = (t) => [f(e1[0] + (e2[0] - e1[0]) * t), f(e1[1] + (e2[1] - e1[1]) * t)];
          const a = p(k / 7), bb = p((k + 1) / 7);
          return `<polygon points="${a} ${bb} 860,${ys[k + 1]} 860,${ys[k]}" fill="${c}"/>`;
        })
        .join('\n    ');
    })()}
  </g>
  <polygon points="520,196 340,566 700,566" fill="url(#glass)"/>
  <polygon points="430,404 575,380 606,444" fill="#FFFFFF" fill-opacity="0.75"/>
  <polygon points="520,196 340,566 700,566" fill="none" stroke="#F2F5FF" stroke-width="22" stroke-linejoin="round"/>
  <path d="M640 64V232Q640 280 688 280H856Z" fill="url(#fold)"/>
  <rect x="248" y="690" width="544" height="216" rx="44" fill="${PALETTE.cyan}"/>
  <g transform="translate(${f(lx)} ${f(ly)}) scale(${scale})">${label.svg}</g>
  <path d="M232 64H640L856 280V912Q856 960 808 960H232Q184 960 184 912V112Q184 64 232 64Z" fill="none" stroke="#FFFFFF" stroke-opacity="0.35" stroke-width="10"/>
</svg>
`;
}

function wordmarkSvg(iconSrc) {
  const t1 = text('Optibench', { w: 11, color: PALETTE.text });
  const t2 = text('Workstation', { w: 7, color: '#AEB9CC' });
  const gap = 30;
  const textW = t1.width + gap + t2.width;
  const icon = 168;
  const pad = 24;
  const tx = pad + icon + 40;
  const W = Math.ceil(tx + textW + pad);
  const H = icon + pad * 2;
  // centre the cap band (y 28..100 in glyph units) vertically on the icon
  const ty = pad + icon / 2 - 64;
  return `<?xml version="1.0" encoding="UTF-8"?>
<!-- Optibench Workstation - horizontal wordmark (light text, for dark backgrounds).
     GENERATED by scripts/build-icons.mjs; lettering is a custom monoline geometric drawn as paths. -->
<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">
  ${embed(iconSrc, 'ic-', pad, pad, icon)}
  <g transform="translate(${tx} ${ty})">${t1.svg}</g>
  <g transform="translate(${f(tx + t1.width + gap)} ${ty})">${t2.svg}</g>
</svg>
`;
}

function sidebarSvg(iconSrc) {
  const W = 164, H = 314;
  const t1 = text('Optibench', { w: 12, color: PALETTE.text });
  const t2 = text('Workstation', { w: 9, color: '#A9B5C9', tracking: 12 });
  const s1 = 128 / t1.width;
  const s2 = 112 / t2.width;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">
  <defs>
    <linearGradient id="sb" x1="0" y1="0" x2="0.35" y2="1">
      <stop offset="0" stop-color="#0E1638"/>
      <stop offset="0.6" stop-color="#0B0F17"/>
      <stop offset="1" stop-color="#170F3A"/>
    </linearGradient>
    <radialGradient id="sg" cx="82" cy="78" r="110" gradientUnits="userSpaceOnUse">
      <stop offset="0" stop-color="#5B6CFF" stop-opacity="0.35"/>
      <stop offset="1" stop-color="#5B6CFF" stop-opacity="0"/>
    </radialGradient>
    <linearGradient id="spec" x1="0" y1="0" x2="1" y2="0">${spectrumStops()}</linearGradient>
  </defs>
  <rect width="${W}" height="${H}" fill="url(#sb)"/>
  <rect width="${W}" height="${H}" fill="url(#sg)"/>
  ${embed(iconSrc, 'ic-', 38, 34, 88)}
  <g transform="translate(${f((W - 128) / 2)} 128) scale(${f(s1)})">${t1.svg}</g>
  <g transform="translate(${f((W - 112) / 2)} 152) scale(${f(s2)})">${t2.svg}</g>
  <rect x="26" y="182" width="112" height="2" rx="1" fill="url(#spec)"/>
  <g fill="none" stroke="${PALETTE.cyan}" stroke-opacity="0.22" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">
    <path d="M0 262H46L58 250H96"/>
    <path d="M0 276H70L82 288H130L140 278H164"/>
    <path d="M164 248H132L122 238H104"/>
  </g>
  <g fill="${PALETTE.cyan}" fill-opacity="0.4">
    <circle cx="96" cy="250" r="2.5"/><circle cx="104" cy="238" r="2.5"/>
  </g>
</svg>`;
}

function headerSvg(iconSrc) {
  const W = 150, H = 57;
  const t1 = text('Optibench', { w: 14, color: PALETTE.text });
  const t2 = text('Workstation', { w: 11, color: '#A9B5C9', tracking: 14 });
  const s1 = 88 / t1.width;
  const s2 = 88 / t2.width;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">
  <defs>
    <linearGradient id="hb" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stop-color="#0E1638"/>
      <stop offset="1" stop-color="#1A1250"/>
    </linearGradient>
    <linearGradient id="spec" x1="0" y1="0" x2="1" y2="0">${spectrumStops()}</linearGradient>
  </defs>
  <rect width="${W}" height="${H}" fill="url(#hb)"/>
  ${embed(iconSrc, 'ic-', 8, 9, 38)}
  <g transform="translate(54 ${f(13 - 28 * s1)}) scale(${f(s1)})">${t1.svg}</g>
  <g transform="translate(54 ${f(30 - 28 * s2)}) scale(${f(s2)})">${t2.svg}</g>
  <rect x="54" y="45" width="88" height="1.5" fill="url(#spec)"/>
</svg>`;
}

// ---------------------------------------------------------------------------
// Rasterisation helpers
// ---------------------------------------------------------------------------
/** Render an SVG (string or Buffer) to a square PNG buffer of `size` px. */
async function renderSquare(svg, size) {
  // Render at 4x then downsample: smoother edges than rsvg at tiny sizes.
  const ss = size <= 64 ? 4 : 1;
  const viewSize = 1024;
  const density = (72 * size * ss) / viewSize;
  return sharp(Buffer.from(svg), { density })
    .resize(size, size, { kernel: 'lanczos3', fit: 'fill' })
    .png({ compressionLevel: 9 })
    .toBuffer();
}

/** Minimal 24-bit uncompressed BMP encoder (BITMAPINFOHEADER, bottom-up rows, BGR). */
function encodeBmp24(rgb, width, height) {
  const rowSize = Math.ceil((width * 3) / 4) * 4;
  const imageSize = rowSize * height;
  const buf = Buffer.alloc(54 + imageSize);
  buf.write('BM', 0, 'ascii');
  buf.writeUInt32LE(54 + imageSize, 2);
  buf.writeUInt32LE(0, 6);
  buf.writeUInt32LE(54, 10);
  buf.writeUInt32LE(40, 14); // DIB header size
  buf.writeInt32LE(width, 18);
  buf.writeInt32LE(height, 22); // positive = bottom-up
  buf.writeUInt16LE(1, 26); // planes
  buf.writeUInt16LE(24, 28); // bpp
  buf.writeUInt32LE(0, 30); // BI_RGB
  buf.writeUInt32LE(imageSize, 34);
  buf.writeInt32LE(2835, 38); // 72 dpi
  buf.writeInt32LE(2835, 42);
  buf.writeUInt32LE(0, 46);
  buf.writeUInt32LE(0, 50);
  for (let y = 0; y < height; y++) {
    const src = y * width * 3;
    const dst = 54 + (height - 1 - y) * rowSize;
    for (let x = 0; x < width; x++) {
      buf[dst + x * 3] = rgb[src + x * 3 + 2];
      buf[dst + x * 3 + 1] = rgb[src + x * 3 + 1];
      buf[dst + x * 3 + 2] = rgb[src + x * 3];
    }
  }
  return buf;
}

async function writeBmp(svg, width, height, outFile) {
  const { data, info } = await sharp(Buffer.from(svg), { density: 72 * 4 })
    .resize(width, height, { kernel: 'lanczos3', fit: 'fill' })
    .flatten({ background: PALETTE.bg })
    .removeAlpha()
    .raw()
    .toBuffer({ resolveWithObject: true });
  if (info.channels !== 3) throw new Error(`expected RGB, got ${info.channels} channels`);
  await writeFile(outFile, encodeBmp24(data, info.width, info.height));
  // PNG preview alongside for quick visual review (not used by the installer)
  await sharp(data, { raw: { width, height, channels: 3 } }).png().toFile(outFile.replace(/\.bmp$/, '.preview.png'));
}

const ICONSET = [
  ['icon_16x16.png', 16], ['icon_16x16@2x.png', 32],
  ['icon_32x32.png', 32], ['icon_32x32@2x.png', 64],
  ['icon_128x128.png', 128], ['icon_128x128@2x.png', 256],
  ['icon_256x256.png', 256], ['icon_256x256@2x.png', 512],
  ['icon_512x512.png', 512], ['icon_512x512@2x.png', 1024],
];
const ICO_SIZES = [16, 24, 32, 48, 64, 128, 256];

/** Produce PNG set + .ico + .iconset for an icon (small variant used for <= 48 px). */
async function iconFamily(name, largeSvg, smallSvg, { pngDir } = {}) {
  const cache = new Map();
  const png = async (size) => {
    if (!cache.has(size)) cache.set(size, await renderSquare(size <= 48 ? smallSvg : largeSvg, size));
    return cache.get(size);
  };
  if (pngDir) {
    await mkdir(pngDir, { recursive: true });
    for (const s of [16, 24, 32, 48, 64, 128, 256, 512, 1024]) await writeFile(path.join(pngDir, `${s}.png`), await png(s));
  }
  const ico = await pngToIco(await Promise.all(ICO_SIZES.map(png)));
  await writeFile(b(`${name}.ico`), ico);
  const setDir = b(`${name}.iconset`);
  await rm(setDir, { recursive: true, force: true });
  await mkdir(setDir, { recursive: true });
  for (const [file, s] of ICONSET) await writeFile(path.join(setDir, file), await png(s));
  if (process.platform === 'darwin') {
    try {
      execFileSync('iconutil', ['-c', 'icns', setDir, '-o', b(`${name}.icns`)]);
      console.log(`  ${name}.icns (iconutil)`);
    } catch (e) {
      console.warn(`  iconutil failed for ${name}: ${e.message}`);
    }
  }
  return png;
}

// ---------------------------------------------------------------------------
async function main() {
  const iconSrc = await readFile(b('icon.svg'), 'utf8');
  const iconSmallSrc = existsSync(b('icon-small.svg')) ? await readFile(b('icon-small.svg'), 'utf8') : iconSrc;

  const fileSrc = fileIconSvg();
  await writeFile(b('file-icon.svg'), fileSrc);
  await writeFile(b('logo-wordmark.svg'), wordmarkSvg(iconSrc));
  console.log('svg: file-icon.svg, logo-wordmark.svg');

  const appPng = await iconFamily('icon', iconSrc, iconSmallSrc, { pngDir: ICONS });
  await writeFile(b('icon.png'), await appPng(512));
  console.log('app icon: icons/*.png, icon.png, icon.ico, icon.iconset/');

  await iconFamily('file-icon', fileSrc, fileSrc);
  console.log('file icon: file-icon.ico, file-icon.iconset/');

  await writeBmp(sidebarSvg(iconSrc), 164, 314, b('installerSidebar.bmp'));
  await writeBmp(headerSvg(iconSmallSrc), 150, 57, b('installerHeader.bmp'));
  console.log('nsis: installerSidebar.bmp (164x314), installerHeader.bmp (150x57)');

  // wordmark preview raster (handy for docs / about box)
  await sharp(Buffer.from(wordmarkSvg(iconSrc)), { density: 144 }).png().toFile(b('logo-wordmark.png'));

  if (process.platform !== 'darwin') {
    console.log('note: run `iconutil -c icns build/icon.iconset -o build/icon.icns` (and file-icon) on macOS.');
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
